suppressPackageStartupMessages({library(SingleCellExperiment);library(data.table);library(jsonlite);library(digest)})
args<-commandArgs(TRUE);root<-normalizePath(args[1]);setwd(root)
stopifnot(basename(root)=='overnight0909',startsWith(normalizePath(tempdir()),paste0(root,'/tmp/')))
out<-file.path(root,'results/fullcell_transfer');dir.create(out,recursive=TRUE,showWarnings=FALSE)
source<-file.path(root,'..','raw_data/lung_cancer/Cords2024/SingleCellExperiment Objects/sce_all_annotated.rds')
story<-file.path(root,'..','story_test_lung')
patients<-fread(file.path(story,'3_dataset/inputs/cords_full527_patients.csv'),colClasses=list(character=c('Patient_ID','batch_id')))
stopifnot(nrow(patients)==527)
cat('Loading provider SCE read-only; exporting the same 527 patients without cell subsampling.\n');flush.console()
sce<-readRDS(source)
markers<-c(CD3='CD3',CD4='CD4',CD8='CD8a',CD31='vWF + CD31',KI67='Ki-67',VIMENTIN='Vimentin',EPI='Pan Cytokeratin + Keratin Epithelial',CD45='CD45RA + CD45R0',HISTONE_H3='Histone H3',HLA_DR='HLA-DR')
stopifnot('counts'%in%assayNames(sce),all(unname(markers)%in%rownames(sce)))
cd<-as.data.table(as.data.frame(colData(sce)[,c('Patient_ID','RoiID','Center_X','Center_Y','cell_category','cell_type','cell_subtype'),drop=FALSE]))
cd[,source_row_id:=.I];cd[,Patient_ID:=as.character(Patient_ID)]
cd<-cd[Patient_ID%chin%patients$Patient_ID]
stopifnot(nrow(cd)==2849385,uniqueN(cd$Patient_ID)==527)
cd<-merge(cd,patients[,.(Patient_ID,batch_id,batch_member_order)],by='Patient_ID',sort=FALSE)
setorder(cd,batch_id,batch_member_order,source_row_id)
x<-t(assay(sce,'counts')[unname(markers),cd$source_row_id,drop=FALSE]);storage.mode(x)<-'double';colnames(x)<-names(markers)
stopifnot(all(is.finite(x)),all(x>=0))
metadata<-cd[,.(dataset='Cords IMC',unit_key=paste0('Cords|',Patient_ID),patient_id=Patient_ID,batch_id,batch_member_order,source_row_id,roi_id=as.character(RoiID),x=as.numeric(Center_X),y=as.numeric(Center_Y),cell_category=as.character(cell_category),cell_type=as.character(cell_type),cell_subtype=as.character(cell_subtype))]
answer<-cbind(metadata,as.data.table(x))
# Verify both cell identity and every exported marker on all previously sampled cells.
sampled<-fread(file.path(story,'3_dataset/inputs/cords_full527_balanced1500_joint10.csv.gz'))
at<-match(sampled$source_row_id,answer$source_row_id);stopifnot(!anyNA(at),all(answer$patient_id[at]==sampled$patient_id))
marker_cols<-names(markers)
max_error<-max(abs(as.matrix(answer[at,..marker_cols])-as.matrix(sampled[,..marker_cols])))
stopifnot(max_error<1e-10)
fwrite(answer,file.path(out,'cords_full527_allcells_joint10.csv.gz'),compress='gzip')
fwrite(answer[cell_category=='Fibroblast',.N,by=.(patient_id,cell_type)],file.path(out,'FULL_CAF_COUNTS.csv'))
manifest<-list(time_utc=format(Sys.time(),tz='UTC',usetz=TRUE),source=source,source_sha256=digest(file=source,algo='sha256',serialize=FALSE),patients=527,total_cells=nrow(answer),CAF_cells=sum(answer$cell_category=='Fibroblast'),sampled_cells_checked=nrow(sampled),sampled_marker_max_error=max_error,selection='Same 527 previously eligible patients; all provider cells, no additional clinical filtering; original counts assay and unchanged labels/coordinates.',script_sha256=digest(file=file.path(root,'scripts/export_full527_cells.R'),algo='sha256',serialize=FALSE))
write_json(manifest,file.path(out,'EXPORT_MANIFEST.json'),pretty=TRUE,auto_unbox=TRUE)
cat('Full-cell export complete:',nrow(answer),'cells;',sum(answer$cell_category=='Fibroblast'),'CAFs.\n')
